import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

export const authMiddleware = (req: Request, res: Response, next: NextFunction): void => {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    res.status(401).json({ success: false, message: 'Authorization token required' });
    return;
  }
  const token = authHeader.split(' ')[1];
  const secret = process.env.JWT_SECRET;
  if (!secret) {
    res.status(500).json({ success: false, message: 'Auth misconfiguration' });
    return;
  }
  try {
    const decoded = jwt.verify(token, secret) as any;
    if (decoded.role !== 'admin' && decoded.role !== 'super_admin') {
      res.status(403).json({ success: false, message: 'Forbidden: Admin access required' });
      return;
    }
    (req as any).user = decoded;
    next();
  } catch (err) {
    res.status(401).json({ success: false, message: 'Invalid or expired token' });
  }
};

import { Request, Response, NextFunction } from 'express';
import crypto from 'crypto';

export const internalAuth = (req: Request, res: Response, next: NextFunction): void => {
  const internalKey = process.env.INTERNAL_SERVICE_KEY;
  if (!internalKey) {
    res.status(500).json({ message: 'Internal auth misconfigured' });
    return;
  }
  const providedKey = req.headers['x-internal-service-key'];
  if (typeof providedKey !== 'string') {
    res.status(403).json({ message: 'Forbidden' });
    return;
  }
  const a = Buffer.from(providedKey);
  const b = Buffer.from(internalKey);
  if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
    res.status(403).json({ message: 'Forbidden: invalid internal service key' });
    return;
  }
  next();
};

